local movement=(function()
local self=require('openmw.self')
local ready,backed,aligned,crossed=false,false,false,false
local timer=0
return {{engineHandlers={{onFrame=function(dt) if not ready then ready=true print('Sewer Player frame ready') end timer=timer+dt if timer>1 then timer=0 print('Sewer crossing position '..tostring(self.position)) end if not backed and self.position.x<=250 then backed=true print('Sewer Player backed away') end if not aligned and self.position.y<=3200 then aligned=true print('Sewer Player on wall centerline') end if not crossed and self.position.x>550 then crossed=true print('Sewer Player crossed wall') end end}}}}

end)()
local combat=require("scripts.sewer_combat_observer")
return {{engineHandlers={{onFrame=function(dt) movement.engineHandlers.onFrame(dt) combat.engineHandlers.onFrame(dt) end}}}}
